 "content": "def transform(grid):
    out = [row[:] for row in grid]
    # Repeated motifs serve as templates: where a later corresponding row
    # differs from its first occurrence, mark those differing cells with 1.
    # Find repeated non-background row patterns, aligned by vertical period.
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]

    # Full-width monochrome rows can establish a template for another row
    # with the same color followed by background cells.
    full_rows = {}
    for i, row in enumerate(grid):
        if all(v == row[0] for v in row):
            full_rows.setdefault(row[0], i)
    for i, row in enumerate(grid):
        color = row[0]
        if color in full_rows and i != full_rows[color]:
            # Template full row identifies changed cells in a related stripe.
            if all(v in (color, bg) for v in row) and any(v == bg for v in row):
                for j, v in enumerate(row):
                    if v != color:
                        out[i][j] = 1
    return out
